/**
 * The figma-style squircle (iOS continuous corners), as an SVG path: the geometry hanji's native
 * `Squircle` draws with fast-squircle. Each corner is a circular arc blended into the straight
 * edge by two cubic Béziers; `smoothing` (0–1) sets how far the blend reaches along the edge.
 */

const rad = (deg: number): number => (deg * Math.PI) / 180;

interface Corner {
  a: number;
  b: number;
  c: number;
  d: number;
  p: number;
  arc: number;
  r: number;
}

function corner(radius: number, smoothing: number, budget: number): Corner {
  const r = Math.min(radius, budget);
  if (r <= 0) return { a: 0, b: 0, c: 0, d: 0, p: 0, arc: 0, r: 0 };
  // keep the curve inside half the shorter side: reduce smoothing before reducing radius
  const s = Math.max(0, Math.min(smoothing, budget / r - 1));
  const p = Math.min((1 + s) * r, budget);
  const arcMeasure = 90 * (1 - s);
  const arc = Math.sin(rad(arcMeasure / 2)) * r * Math.SQRT2;
  const alpha = (90 - arcMeasure) / 2;
  const p3ToP4 = r * Math.tan(rad(alpha / 2));
  const beta = 45 * s;
  const c = p3ToP4 * Math.cos(rad(beta));
  const d = c * Math.tan(rad(beta));
  const b = (p - arc - c - d) / 3;
  const a = 2 * b;
  return { a, b, c, d, p, arc, r };
}

const n = (v: number): string => (Math.round(v * 100) / 100).toString();

/**
 * SVG path data for a `width × height` squircle.
 *
 * @param radius     corner radius in px (clamped to half the shorter side)
 * @param smoothing  0 = circular corners · .72 = hanji · 1 = most continuous
 */
export function squirclePath(
  width: number,
  height: number,
  radius: number,
  smoothing = 0.72,
): string {
  const k = corner(radius, smoothing, Math.min(width, height) / 2);
  const { a, b, c, d, p, arc, r } = k;
  if (r === 0) return `M0 0H${n(width)}V${n(height)}H0Z`;
  return [
    `M${n(width - p)} 0`,
    `c${n(a)} 0 ${n(a + b)} 0 ${n(a + b + c)} ${n(d)}`,
    `a${n(r)} ${n(r)} 0 0 1 ${n(arc)} ${n(arc)}`,
    `c${n(d)} ${n(c)} ${n(d)} ${n(b + c)} ${n(d)} ${n(a + b + c)}`,
    `L${n(width)} ${n(height - p)}`,
    `c0 ${n(a)} 0 ${n(a + b)} ${n(-d)} ${n(a + b + c)}`,
    `a${n(r)} ${n(r)} 0 0 1 ${n(-arc)} ${n(arc)}`,
    `c${n(-c)} ${n(d)} ${n(-(b + c))} ${n(d)} ${n(-(a + b + c))} ${n(d)}`,
    `L${n(p)} ${n(height)}`,
    `c${n(-a)} 0 ${n(-(a + b))} 0 ${n(-(a + b + c))} ${n(-d)}`,
    `a${n(r)} ${n(r)} 0 0 1 ${n(-arc)} ${n(-arc)}`,
    `c${n(-d)} ${n(-c)} ${n(-d)} ${n(-(b + c))} ${n(-d)} ${n(-(a + b + c))}`,
    `L0 ${n(p)}`,
    `c0 ${n(-a)} 0 ${n(-(a + b))} ${n(d)} ${n(-(a + b + c))}`,
    `a${n(r)} ${n(r)} 0 0 1 ${n(arc)} ${n(-arc)}`,
    `c${n(c)} ${n(-d)} ${n(b + c)} ${n(-d)} ${n(a + b + c)} ${n(-d)}`,
    'Z',
  ].join(' ');
}

/** CSS `corner-shape` matching a smoothing — use with border-radius × (1 + smoothing). */
export { cornerShapeFor as cornerShape } from '@hanji/tokens';

@layer hj.components {
  /*
   * A continuous-corner surface. --hj-squircle-radius / -shape / -span come from props.
   * Where corner-shape exists the radius grows by (1 + smoothing) — the figma curve starts that
   * far along each edge — and the superellipse is fitted to it. Elsewhere: circular, or the exact
   * clip-path when the component measures itself.
   */
  .hj-squircle {
    border-radius: var(--hj-squircle-radius, var(--hj-r-md));
    corner-shape: var(--hj-squircle-shape, var(--hj-corner-shape, round));
  }
  @supports (corner-shape: superellipse(2)) {
    .hj-squircle:not([data-clipped]) {
      border-radius: calc(var(--hj-squircle-radius, var(--hj-r-md)) * var(--hj-squircle-span, 1));
    }
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { cornerShape, squirclePath } from './squircle-path.ts';

export { cornerShape, squirclePath } from './squircle-path.ts';

const supportsCornerShape = (): boolean =>
  typeof CSS !== 'undefined' &&
  typeof CSS.supports === 'function' &&
  CSS.supports('corner-shape', 'superellipse(2)');

/** Props hanji adds. */
export interface SquircleOwnProps {
  /** A radius token or px. @default 'md' */
  radius?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | number;
  /** 0 = circular · .72 = hanji (default) · 1 = most continuous. */
  smoothing?: number;
  /**
   * Draw with a measured clip-path even where CSS corner-shape exists — pixel-identical to the
   * native library. Default: only when corner-shape is unsupported.
   */
  exact?: boolean;
}

export interface SquircleProps
  extends SquircleOwnProps, Omit<React.ComponentProps<'div'>, 'className'> {
  className?: string;
  render?: useRender.RenderProp;
}

/**
 * A continuous-corner surface (hanji `Squircle`). Uses CSS `corner-shape` where the browser has
 * it — zero JavaScript — and otherwise clips to the exact figma squircle, re-measured on resize.
 * Clip-path also clips focus rings and shadows, so prefer it for art, avatars and tiles.
 */
export function Squircle(props: SquircleProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    radius = 'md',
    smoothing = 0.72,
    exact = false,
    render,
    className,
    style,
    ...rest
  } = withDefaults(config, 'Squircle', props);
  const ref = React.useRef<HTMLElement>(null);
  const [clip, setClip] = React.useState<string | undefined>(undefined);

  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || (!exact && supportsCornerShape())) {
      setClip(undefined);
      return undefined;
    }
    const px = (): number =>
      typeof radius === 'number'
        ? radius
        : Number.parseFloat(getComputedStyle(el).borderTopLeftRadius) || 0;
    const measure = (): void => {
      const { width, height } = el.getBoundingClientRect();
      if (width > 0 && height > 0)
        setClip(`path('${squirclePath(width, height, px(), smoothing)}')`);
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [radius, smoothing, exact, ref]);

  const radiusValue = typeof radius === 'number' ? `${radius}px` : `var(--hj-r-${radius})`;
  const own = {
    '--hj-squircle-radius': radiusValue,
    '--hj-squircle-shape': cornerShape(smoothing),
    '--hj-squircle-span': String(1 + Math.max(0, Math.min(1, smoothing))),
    ...(clip ? { clipPath: clip, borderRadius: 0 } : null),
    ...style,
  } as React.CSSProperties;

  return useRender({
    render,
    ref,
    defaultTagName: 'div',
    props: {
      ...rest,
      'data-clipped': clip ? '' : undefined,
      className: cls(config, 'Squircle', 'hj-squircle', className) as string | undefined,
      style: own,
    },
  });
}
